    "row": 3,
    "title": "We are for: For Filmmaking.  Advertising.  Social Media.  Marketing.",
    "variation": "34",
    "prefix": "r3v34",
    "source": "~/BGit/all/film/marketing/ACT3_marketing_Home/act3/rows/row_3_who_we_are_for/v/34",
    "html": "<section class=\"r3v34-row\" aria-labelledby=\"r3v34-title\">\n  <header class=\"r3v34-head\">\n    <div>\n      <p class=\"r3v34-eyebrow\">For filmmaking, advertising, social media, marketing</p>\n      <h2 class=\"r3v34-title\" id=\"r3v34-title\">Spend the hours on the idea.</h2>\n    </div>\n    <p class=\"r3v34-sub\">Describe a character, a set or a look once and it carries through every shot. The time you get back is yours, whichever of these you make.</p>\n  </header>\n  <ol class=\"r3v34-wall\">\n    <li class=\"r3v34-panel\">\n      <img class=\"r3v34-img\" src=\"/v4/row_3/v/air_film.jpg\" alt=\"A dark movie theater, Jack and Sally on the big screen\" width=\"1000\" height=\"1000\" loading=\"lazy\">\n      <div class=\"r3v34-third\"><h3 class=\"r3v34-name\">Filmmaking</h3><p class=\"r3v34-line\">Your hours go to the story, not the setup.</p></div>\n    </li>\n    <li class=\"r3v34-panel\">\n      <img class=\"r3v34-img\" src=\"/v4/row_3/v/air_ad.jpg\" alt=\"A city billboard at night showing the striped surfboard ad\" width=\"1000\" height=\"1000\" loading=\"lazy\">\n      <div class=\"r3v34-third\"><h3 class=\"r3v34-name\">Advertising</h3><p class=\"r3v34-line\">Your hours go to the concept, not the rework.</p></div>\n    </li>\n    <li class=\"r3v34-panel\">\n      <img class=\"r3v34-img\" src=\"/v4/row_3/v/air_social.jpg\" alt=\"A hand holding a phone at night with a vertical video of Sally and Jack\" width=\"1000\" height=\"1000\" loading=\"lazy\">\n      <div class=\"r3v34-third\"><h3 class=\"r3v34-name\">Social media</h3><p class=\"r3v34-line\">Your hours go to the idea, not the repeat work.</p></div>\n    </li>\n    <li class=\"r3v34-panel\">\n      <img class=\"r3v34-img\" src=\"/v4/row_3/v/air_marketing.jpg\" alt=\"A surf shop window display at night showing the brand video\" width=\"1000\" height=\"1000\" loading=\"lazy\">\n      <div class=\"r3v34-third\"><h3 class=\"r3v34-name\">Marketing</h3><p class=\"r3v34-line\">Your hours go to the message, not the production line.</p></div>\n    </li>\n  </ol>\n  <svg class=\"r3v34-rails\" viewBox=\"0 0 1000 110\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n    <path class=\"r3v34-rail\" d=\"M125 0 C125 70 500 40 500 110\"/>\n    <path class=\"r3v34-rail\" d=\"M375 0 C375 60 500 50 500 110\"/>\n    <path class=\"r3v34-rail\" d=\"M625 0 C625 60 500 50 500 110\"/>\n    <path class=\"r3v34-rail\" d=\"M875 0 C875 70 500 40 500 110\"/>\n  </svg>\n  <div class=\"r3v34-hub\">\n    <p class=\"r3v34-hub-title\">One ACT 3 project</p>\n    <ul class=\"r3v34-hub-list\">\n      <li>One cast</li><li>One set library</li><li>One editor</li><li>Your whole team</li>\n    </ul>\n  </div>\n</section>",
    "css": ".v4 .r3v34-row { --r3v34-bg: #1C1B20; --r3v34-ink: #F6F5F2; --r3v34-muted: #C8C7CC; --r3v34-accent: #EEBC3C; --r3v34-band: #000000; --r3v34-rail: #EEBC3C; --r3v34-hub: #0F0E0C; --r3v34-gutter: clamp(18px, 4vw, 48px); box-sizing: border-box; width: 100%; color: var(--r3v34-ink); background: var(--r3v34-bg); overflow: hidden; font-family: \"Rubik\", system-ui, -apple-system, \"Segoe UI\", Roboto, Arial, sans-serif; padding: clamp(56px, 6.5vw, 92px) 0 clamp(56px, 6.5vw, 92px); -webkit-font-smoothing: antialiased; }\n.v4[data-v4-theme=\"light\"] .r3v34-row { --r3v34-bg: #F4F4F5; --r3v34-ink: #131216; --r3v34-muted: #46454B; --r3v34-band: #131216; --r3v34-rail: #B58A16; --r3v34-hub: #151419; }\n.v4 .r3v34-row *,\n.v4 .r3v34-row *::before,\n.v4 .r3v34-row *::after { box-sizing: border-box; }\n.v4 .r3v34-head { max-width: 1320px; margin: 0 auto clamp(30px, 4vw, 48px); padding: 0 clamp(18px, 4vw, 48px); display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: clamp(18px, 4vw, 56px); align-items: end; }\n.v4 .r3v34-eyebrow { margin: 0 0 12px; font-size: 16px; font-weight: 500; color: var(--r3v34-muted); }\n.v4 .r3v34-title { margin: 0; font-size: clamp(36px, 5vw, 70px); font-weight: 800; letter-spacing: -0.035em; line-height: 1; }\n.v4 .r3v34-sub { margin: 0; font-size: clamp(17px, 1.4vw, 20px); line-height: 1.55; color: var(--r3v34-muted); }\n.v4 .r3v34-wall { list-style: none; margin: 0; padding: 14px 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 3px; background: var(--r3v34-band); }\n.v4 .r3v34-panel { position: relative; margin: 0; overflow: hidden; background: #0F0E0C; aspect-ratio: 1 / 1.08; }\n.v4 .r3v34-img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: 50% 30%; }\n.v4 .r3v34-third { position: absolute; left: 0; right: 14%; bottom: clamp(14px, 1.8vw, 26px); color: #F6F5F2; }\n.v4 .r3v34-name { display: inline-block; margin: 0; padding: 7px 16px 6px clamp(14px, 1.6vw, 24px); background: #EEBC3C; color: #151419; font-size: clamp(20px, 1.9vw, 27px); font-weight: 800; letter-spacing: -0.01em; text-transform: uppercase; line-height: 1.1; }\n.v4 .r3v34-line { margin: 0; padding: 10px 14px 11px clamp(14px, 1.6vw, 24px); background: rgba(8,8,8,0.9); border-left: 5px solid #EEBC3C; font-size: 16px; font-weight: 500; line-height: 1.38; }\n.v4 .r3v34-js .r3v34-third { transform: translateX(-104%); transition: transform 0.7s cubic-bezier(.2,.8,.2,1); }\n.v4 .r3v34-js .r3v34-panel:nth-child(2) .r3v34-third { transition-delay: 0.12s; }\n.v4 .r3v34-js .r3v34-panel:nth-child(3) .r3v34-third { transition-delay: 0.24s; }\n.v4 .r3v34-js .r3v34-panel:nth-child(4) .r3v34-third { transition-delay: 0.36s; }\n.v4 .r3v34-js.r3v34-in .r3v34-third { transform: none; }\n.v4 .r3v34-rails { display: block; width: 100%; height: clamp(72px, 8vw, 120px); overflow: visible; }\n.v4 .r3v34-rail { fill: none; stroke: var(--r3v34-rail); stroke-width: 2.5; vector-effect: non-scaling-stroke; }\n.v4 .r3v34-js .r3v34-rails { clip-path: inset(0 0 100% 0); transition: clip-path 1.3s ease; }\n.v4 .r3v34-js.r3v34-wired .r3v34-rails { clip-path: inset(0 0 -4px 0); }\n.v4 .r3v34-hub { width: min(860px, calc(100% - 2 * var(--r3v34-gutter))); margin: 0 auto; padding: 18px clamp(16px, 3vw, 32px) 20px; text-align: center; background: var(--r3v34-hub); color: #F6F5F2; border: 2px solid var(--r3v34-accent); border-radius: 16px; }\n.v4 .r3v34-hub-title { margin: 0 0 12px; font-size: clamp(20px, 1.8vw, 26px); font-weight: 800; letter-spacing: -0.01em; }\n.v4 .r3v34-hub-list { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; justify-content: center; gap: 8px 10px; }\n.v4 .r3v34-hub-list li { padding: 7px 14px; border-radius: 999px; background: #29282D; font-size: 16px; font-weight: 500; }\n.v4 .r3v34-hub-list li::before { content: \"\"; display: inline-block; width: 8px; height: 8px; margin-right: 8px; border-radius: 50%; background: #EEBC3C; vertical-align: middle; }\n@media (max-width: 1000px) {\n.v4 .r3v34-head { grid-template-columns: minmax(0, 1fr); }\n.v4 .r3v34-wall { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n.v4 .r3v34-rails { display: none; }\n.v4 .r3v34-hub { position: relative; margin-top: 44px; }\n.v4 .r3v34-hub::before { content: \"\"; position: absolute; left: 50%; top: -46px; width: 2.5px; height: 44px; margin-left: -1.25px; background: var(--r3v34-rail); }\n}\n@media (max-width: 560px) {\n.v4 .r3v34-wall { grid-template-columns: minmax(0, 1fr); }\n.v4 .r3v34-panel { aspect-ratio: 4 / 3.3; }\n.v4 .r3v34-third { right: 8%; }\n}\n@media (prefers-reduced-motion: reduce) {\n.v4 .r3v34-js .r3v34-third { transform: none; transition: none; }\n.v4 .r3v34-js .r3v34-rails { clip-path: none; transition: none; }\n}",
